package com.fream.back.visible.t06;

import com.fream.back.domain.notification.entity.Notification;
import com.fream.back.domain.notification.entity.NotificationType;
import com.fream.back.domain.product.entity.Interest;
import com.fream.back.domain.product.entity.Product;
import com.fream.back.domain.product.entity.ProductColor;
import com.fream.back.domain.product.entity.ProductSize;
import com.fream.back.domain.product.entity.enumType.GenderType;
import com.fream.back.domain.product.entity.enumType.SizeType;
import com.fream.back.domain.sale.service.command.SaleBidCommandService;
import com.fream.back.domain.user.entity.BankAccount;
import com.fream.back.domain.user.entity.User;
import com.fream.back.global.config.QueryDslConfig;
import jakarta.persistence.EntityManager;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.jdbc.AutoConfigureTestDatabase;
import org.springframework.boot.test.autoconfigure.orm.jpa.DataJpaTest;
import org.springframework.context.ApplicationContext;
import org.springframework.context.annotation.Import;
import org.springframework.test.context.ActiveProfiles;

import java.util.List;

import static org.assertj.core.api.Assertions.assertThat;

/**
 * 새 판매 입찰이 등록되면 그 상품 색상을 관심 등록한 회원이 알림을 받는지 본다.
 */
@DataJpaTest
@AutoConfigureTestDatabase(replace = AutoConfigureTestDatabase.Replace.NONE)
@ActiveProfiles("test")
@Import(QueryDslConfig.class)
class ListingAlertTest {

    @Autowired EntityManager em;
    @Autowired ApplicationContext ctx;

    private static int seq = 0;

    private User user(String prefix) {
        seq++;
        User u = User.builder().email(prefix + "-v6-" + seq + "@test.com").password("pw").referralCode("v6-" + seq)
                .phoneNumber("010-6000-" + seq).build();
        em.persist(u);
        return u;
    }

    private List<Notification> favoriteAlertsOf(User u) {
        return em.createQuery("select n from Notification n where n.user.id = :uid", Notification.class)
                .setParameter("uid", u.getId()).getResultList().stream()
                .filter(n -> n.getType() == NotificationType.FAVORITE).toList();
    }

    @Test
    void newListingAlertsUsersInterestedInThatColorOnly() {
        User seller = user("seller");
        em.persist(BankAccount.builder().user(seller).bankName("국민").accountNumber("111-222").accountHolder("판매자").build());
        User whiteFan = user("white-fan");
        User blackFan = user("black-fan");

        Product product = Product.builder().name("에어 포스 1").englishName("Air Force 1").releasePrice(139000)
                .modelNumber("AF-1").releaseDate("2024-01-01").gender(GenderType.UNISEX).build();
        em.persist(product);
        ProductColor white = ProductColor.builder().colorName("White").product(product).build();
        ProductColor black = ProductColor.builder().colorName("Black").product(product).build();
        em.persist(white);
        em.persist(black);
        ProductSize white260 = ProductSize.builder().sizeType(SizeType.SHOES).size("260")
                .purchasePrice(139000).salePrice(139000).quantity(1).productColor(white).build();
        em.persist(white260);
        em.persist(Interest.builder().user(whiteFan).productColor(white).build());
        em.persist(Interest.builder().user(blackFan).productColor(black).build());
        em.flush();
        em.clear();

        new Wiring(ctx).get(SaleBidCommandService.class)
                .createSaleBid(seller.getEmail(), white260.getId(), 150000, "서울", "12345", "010-0000-0000", false);
        em.flush();
        em.clear();

        List<Notification> alerts = favoriteAlertsOf(whiteFan);
        assertThat(alerts).hasSize(1);
        assertThat(alerts.get(0).getMessage()).contains("에어 포스 1");
        assertThat(favoriteAlertsOf(blackFan)).isEmpty();
    }
}
package com.fream.back.visible.t06;

import org.mockito.Mockito;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.context.ApplicationContext;
import org.springframework.context.ApplicationEvent;
import org.springframework.context.ApplicationEventPublisher;
import org.springframework.context.PayloadApplicationEvent;
import org.springframework.context.annotation.ClassPathScanningCandidateComponentProvider;
import org.springframework.context.event.EventListener;
import org.springframework.core.type.filter.AnnotationTypeFilter;
import org.springframework.stereotype.Component;
import org.springframework.transaction.event.TransactionalEventListener;

import java.lang.reflect.Constructor;
import java.lang.reflect.Field;
import java.lang.reflect.InvocationTargetException;
import java.lang.reflect.Method;
import java.lang.reflect.Modifier;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;

/**
 * 테스트용 객체 조립기.
 *
 * - 리포지토리·EntityManager 등 테스트 컨텍스트(@DataJpaTest)에 있는 빈은 그대로 쓴다.
 * - com.fream.back.domain 아래의 @Service/@Component 클래스는 실제 객체로 생성자 주입해 만든다.
 * - 그 밖의 의존(외부 연동·Redis·WebSocket 등)은 Mockito mock으로 채운다.
 * - ApplicationEventPublisher로 발행한 이벤트는 domain 아래 @EventListener/@TransactionalEventListener 메서드로 즉시 전달한다.
 */
final class Wiring {

    private static final String DOMAIN = "com.fream.back.domain";

    private final ApplicationContext ctx;
    private final Map<Class<?>, Object> instances = new HashMap<>();
    private final Set<Class<?>> building = new HashSet<>();
    private List<Class<?>> listenerClasses;

    Wiring(ApplicationContext ctx) {
        this.ctx = ctx;
        instances.put(ApplicationEventPublisher.class, (ApplicationEventPublisher) this::dispatch);
    }

    <T> Wiring with(Class<T> type, T instance) {
        instances.put(type, instance);
        return this;
    }

    @SuppressWarnings("unchecked")
    <T> T get(Class<T> type) {
        Object existing = instances.get(type);
        if (existing != null) {
            return (T) existing;
        }
        if (type == String.class) {
            return (T) "";
        }
        if (type.isPrimitive()) {
            return (T) defaultPrimitive(type);
        }
        Object bean = ctx.getBeanProvider(type).getIfUnique();
        if (bean != null) {
            return (T) bean;
        }
        Object created;
        if (isDomainComponent(type) && !building.contains(type)) {
            building.add(type);
            try {
                created = construct(type);
            } finally {
                building.remove(type);
            }
        } else {
            created = Mockito.mock(type);
        }
        instances.put(type, created);
        return (T) created;
    }

    private static boolean isDomainComponent(Class<?> t) {
        return t.getName().startsWith(DOMAIN + ".")
                && !t.isInterface()
                && !Modifier.isAbstract(t.getModifiers())
                && org.springframework.core.annotation.AnnotatedElementUtils.hasAnnotation(t, Component.class);
    }

    private Object construct(Class<?> type) {
        try {
            Constructor<?> ctor = null;
            for (Constructor<?> c : type.getDeclaredConstructors()) {
                if (c.isAnnotationPresent(Autowired.class)) {
                    ctor = c;
                }
            }
            if (ctor == null) {
                ctor = java.util.Arrays.stream(type.getDeclaredConstructors())
                        .max(Comparator.comparingInt(Constructor::getParameterCount))
                        .orElseThrow();
            }
            Class<?>[] params = ctor.getParameterTypes();
            Object[] args = new Object[params.length];
            for (int i = 0; i < params.length; i++) {
                args[i] = get(params[i]);
            }
            ctor.setAccessible(true);
            Object obj = ctor.newInstance(args);
            instances.put(type, obj);
            for (Class<?> c = type; c != null && c != Object.class; c = c.getSuperclass()) {
                for (Field f : c.getDeclaredFields()) {
                    if (f.isAnnotationPresent(Autowired.class) && !Modifier.isStatic(f.getModifiers())) {
                        f.setAccessible(true);
                        if (f.get(obj) == null) {
                            f.set(obj, get(f.getType()));
                        }
                    }
                }
            }
            return obj;
        } catch (ReflectiveOperationException e) {
            throw new IllegalStateException("cannot build " + type.getName(), e);
        }
    }

    private void dispatch(Object event) {
        Object payload = (event instanceof PayloadApplicationEvent<?> p) ? p.getPayload() : event;
        for (Class<?> listenerType : listenerClasses()) {
            for (Method m : listenerType.getDeclaredMethods()) {
                boolean listener = m.isAnnotationPresent(EventListener.class)
                        || m.isAnnotationPresent(TransactionalEventListener.class);
                if (!listener || m.getParameterCount() != 1) {
                    continue;
                }
                Class<?> p = m.getParameterTypes()[0];
                Object arg = p.isInstance(payload) ? payload
                        : (event instanceof ApplicationEvent && p.isInstance(event)) ? event : null;
                if (arg == null) {
                    continue;
                }
                try {
                    m.setAccessible(true);
                    m.invoke(get(listenerType), arg);
                } catch (InvocationTargetException e) {
                    Throwable t = e.getTargetException();
                    if (t instanceof RuntimeException re) {
                        throw re;
                    }
                    throw new IllegalStateException(t);
                } catch (IllegalAccessException e) {
                    throw new IllegalStateException(e);
                }
            }
        }
    }

    private List<Class<?>> listenerClasses() {
        if (listenerClasses == null) {
            listenerClasses = new ArrayList<>();
            ClassPathScanningCandidateComponentProvider scanner = new ClassPathScanningCandidateComponentProvider(false);
            scanner.addIncludeFilter(new AnnotationTypeFilter(Component.class));
            scanner.findCandidateComponents(DOMAIN).forEach(bd -> {
                try {
                    Class<?> c = Class.forName(bd.getBeanClassName());
                    for (Method m : c.getDeclaredMethods()) {
                        if (m.isAnnotationPresent(EventListener.class)
                                || m.isAnnotationPresent(TransactionalEventListener.class)) {
                            listenerClasses.add(c);
                            break;
                        }
                    }
                } catch (ClassNotFoundException | LinkageError ignored) {
                    // 로드할 수 없는 후보는 건너뛴다
                }
            });
        }
        return listenerClasses;
    }

    private static Object defaultPrimitive(Class<?> t) {
        if (t == boolean.class) return false;
        if (t == char.class) return '\0';
        if (t == byte.class) return (byte) 0;
        if (t == short.class) return (short) 0;
        if (t == int.class) return 0;
        if (t == long.class) return 0L;
        if (t == float.class) return 0f;
        return 0d;
    }
}
package com.fream.back.domain.sale.service.command;

import com.fream.back.domain.order.entity.OrderBid;
import com.fream.back.domain.order.service.query.OrderBidQueryService;
import com.fream.back.domain.product.entity.ProductSize;
import com.fream.back.domain.product.service.productSize.ProductSizeQueryService;
import com.fream.back.domain.sale.entity.BidStatus;
import com.fream.back.domain.sale.entity.Sale;
import com.fream.back.domain.sale.entity.SaleBid;
import com.fream.back.domain.sale.repository.SaleBidRepository;
import com.fream.back.domain.user.entity.User;
import com.fream.back.domain.user.service.query.UserQueryService;
import lombok.RequiredArgsConstructor;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
@RequiredArgsConstructor
public class SaleBidCommandService {

    private final SaleBidRepository saleBidRepository;
    private final UserQueryService userQueryService;
    private final ProductSizeQueryService productSizeQueryService;
    private final SaleCommandService saleCommandService;
    private final OrderBidQueryService orderBidQueryService;
    @Transactional
    public SaleBid createSaleBid(String sellerEmail, Long productSizeId, int bidPrice,
                                 String returnAddress, String postalCode, String receiverPhone
                                , boolean isWarehouseStorage) {
        // 1. User 조회
        User seller = userQueryService.findByEmail(sellerEmail);

        // 2. ProductSize 조회
        ProductSize productSize = productSizeQueryService.findById(productSizeId)
                .orElseThrow(() -> new IllegalArgumentException("해당 상품 사이즈를 찾을 수 없습니다: " + productSizeId));

        // 3. Sale 생성
        Sale sale = saleCommandService.createSale(seller, productSize, returnAddress, postalCode, receiverPhone,isWarehouseStorage);

        // 4. SaleBid 생성
        SaleBid saleBid = SaleBid.builder()
                .seller(seller)
                .productSize(productSize)
                .bidPrice(bidPrice)
                .status(BidStatus.PENDING)
                .sale(sale) // 연관된 Sale 설정
                .build();

        // 5. SaleBid 저장
        saleBid = saleBidRepository.save(saleBid);

        // 6. Sale에 SaleBid 추가 (연관관계 설정)
        sale.assignSaleBid(saleBid);

        // 7. SaleBid 반환
        return saleBid;
    }
    @Transactional
    public Long createInstantSaleBid(Long orderBidId,
                                        String sellerEmail,
                                        String returnAddress,
                                        String postalCode,
                                        String receiverPhone) {

        Sale sale=saleCommandService.createInstantSale(orderBidId,sellerEmail,returnAddress,postalCode,receiverPhone);
        // 1. OrderBid 조회
        OrderBid orderBid = orderBidQueryService.findById(orderBidId)
                .orElseThrow(() -> new IllegalArgumentException("해당 OrderBid를 찾을 수 없습니다."));


        // 3. SaleBid 생성
        SaleBid saleBid = SaleBid.builder()
                .seller(sale.getSeller()) // Sale의 판매자
                .productSize(sale.getProductSize()) // Sale의 ProductSize
                .bidPrice(orderBid.getBidPrice()) // OrderBid의 입찰 가격 사용
                .status(BidStatus.MATCHED) // 즉시 판매는 바로 매칭 상태
                .sale(sale) // Sale과 매핑
                .order(orderBid.getOrder()) // Order와 매핑
                .build();

        // 양방향 관계 설정
        saleBid.assignSale(sale);
        saleBid.assignOrder(orderBid.getOrder());
        sale.assignSaleBid(saleBid); // Sale과 SaleBid 양방향 연관관계 설정

        // SaleBid 저장
        saleBidRepository.save(saleBid);

        // Sale ID 반환
        return sale.getId();
    }

    @Transactional
    public void deleteSaleBid(Long saleBidId) {
        // SaleBid 조회
        SaleBid saleBid = saleBidRepository.findById(saleBidId)
                .orElseThrow(() -> new IllegalArgumentException("해당 SaleBid를 찾을 수 없습니다: " + saleBidId));

        // Order와 연결 여부 확인
        if (saleBid.getOrder() != null) {
            throw new IllegalStateException("SaleBid는 Order와 연결되어 있으므로 삭제할 수 없습니다.");
        }

        // Sale과 연결 여부 확인 후 삭제
        if (saleBid.getSale() != null) {
            saleCommandService.deleteSale(saleBid.getSale().getId());
        }

        // SaleBid 삭제
        saleBidRepository.delete(saleBid);
    }
}
